use verus::prelude::*;

verus! {
    // Swaps the first and last elements of a non‐empty vector in place.
    // 
    // Requirements:
    //  - a.len() >= 1
    //
    // Guarantees:
    //  - The length of `a` is unchanged.
    //  - The new first element is the old last element.
    //  - The new last element is the old first element.
    //  - All elements strictly between remain exactly as they were.
    fn swap_first_and_last(a: &mut Vec<i32>)
        requires
            a.len() >= 1,
        ensures
            // Length unchanged
            a.len() == old(a.len()),
        ensures
            // New first element is the old last element
            a[0] == old(a[old(a.len()) - 1]),
        ensures
            // New last element is the old first element
            a[a.len() - 1] == old(a[0]),
        ensures
            // Everything in between is unchanged
            forall |i: usize|
                0 < i && i < a.len() - 1
                ==> a[i] == old(a[i]),
    {
        // Safe because requires a.len() >= 1
        let last_idx = a.len() - 1;

        // Perform the swap
        let tmp = a[0];
        a[0] = a[last_idx];
        a[last_idx] = tmp;
    }
}